/**
 * Database Configuration — PostgreSQL with Sequelize
 * Generated by BackendForge
 */

const { Sequelize } = require('sequelize');
const { env } = require('./env');
const winston = require('winston');

const logger = winston.createLogger({ level: env.LOG_LEVEL });

const sequelize = new Sequelize(env.DATABASE_URL, {
  dialect: 'postgres',
  logging: false,
  define: {
    timestamps: true,
    underscored: true,
    paranoid: true,
    freezeTableName: true,
  }
});

const connectDB = async () => {
  try {
    logger.info(`Skipping database connection for demonstration so you can view the API Docs!`);
    return sequelize;
  } catch (error) {
    logger.error(`Database connection failed: ${error.message}`);
  }
};

const disconnectDB = async () => {
  await sequelize.close();
  logger.info('Database connection closed');
};

module.exports = { sequelize, connectDB, disconnectDB };
